const p = $('Normaliza payload').first().json;
const c = $('Dados do cliente e intenção').first().json;
const b = $('Busca barbearia').first().json;
let sessao = $input.first().json || {};

const txt = String(p.mensagem_texto || '').trim().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
const pediuRecomeco = /^(menu|recomecar|reiniciar|inicio|voltar)$/.test(txt);

// Sessão encerrada (agendamento concluído), sem etapa ou pedido de recomeço: volta ao início do fluxo
if (!sessao.etapa_atual || sessao.etapa_atual === 'concluido' || pediuRecomeco) {
  sessao = { ...sessao, etapa_atual: c.nome_cliente ? '00201' : '00101', aguardando_resposta: false };
}

return [{ json: {
  barbearia_id: b.id,
  id_cliente: c.id_cliente,
  telefone: p.telefone,
  instancia: p.instancia,
  mensagem_texto: p.mensagem_texto,
  nome_cliente: c.nome_cliente,
  sessao
} }];

const ZONA = 'America/Sao_Paulo';
const e = $('Monta entrada da etapa').first().json;
const s = e.sessao || {};
const agora = DateTime.now().setZone(ZONA);
const atends = $input.all().map(i => i.json).filter(a => a.id);
const txt = String(e.mensagem_texto || '').trim().toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');

const inicio = (a) => DateTime.fromISO(a.data_agend + 'T' + String(a.horario).slice(0, 8), { zone: ZONA });
const desc = (a) => inicio(a).toFormat('dd/MM') + ' às ' + inicio(a).toFormat('HH:mm');
const prof = (a) => (a.profissionais && a.profissionais.nome) ? ' com ' + a.profissionais.nome : '';

const futuros = atends.filter(a => inicio(a) > agora).sort((x, y) => inicio(x) - inicio(y));
const proximo = futuros[0] || null;
// Pedido de NPS enviado e ainda sem nota, de um atendimento dos últimos 3 dias
const npsPendente = atends
  .filter(a => a.nps_solicitado && a.nps == null && inicio(a) < agora && agora.diff(inicio(a), 'days').days <= 3)
  .sort((x, y) => inicio(y) - inicio(x))[0] || null;

// Nota de 1 a 5 (mesma escala do CRM e da regra atendimentos_nps_check)
const mNota = txt.match(/^(?:nota\s*)?([1-5])(?:\s*\/\s*5)?\s*(?:estrelas?)?\s*[!.]*$/);
const nota = mNota ? Number(mNota[1]) : null;
// Números no meio do agendamento são respostas do fluxo (serviço, profissional, horário), não nota
const emAgendamento = Boolean(s.aguardando_resposta) && ['00101', '00201', '00301', '00401', '00501'].includes(s.etapa_atual);
const querCancelar = /\b(cancelar|cancela|cancelamento|desmarcar|desmarca)\b/.test(txt);
const querRemarcar = /\b(remarcar|remarca|remarcacao|reagendar|reagenda)\b/.test(txt) || /(trocar|mudar|alterar) (o |meu )?(horario|dia)/.test(txt);
const sim = /^(sim|s|ss|confirmo|confirmar|pode|isso|ok|quero)\b/.test(txt);
const nao = /^(nao|n|deixa|esquece|manter|mantem|mantenha|desisto)\b/.test(txt);

const out = { ...e, acao: 'fluxo', texto: '', sessao_patch: null, cliente_patch: null, alvo_id: null, nota: null, entrada_remarcar: null };
const concluir = { etapa_atual: 'concluido', aguardando_resposta: false, id_atend_alvo: null };

function remarcar(a) {
  const servicos = (a.atendimento_servicos || []).map(x => x.servico_id).filter(Boolean);
  const patch = { etapa_atual: '00401', aguardando_resposta: false, id_atend_alvo: a.id, servicos_selecionados: servicos, id_prof_selecionado: a.id_prof, dia_selecionado: null, horario_selecionado: null };
  out.acao = 'remarcar';
  out.alvo_id = a.id;
  out.sessao_patch = patch;
  out.texto = 'Vamos remarcar seu horário de ' + desc(a) + prof(a) + ' 🔄';
  out.entrada_remarcar = { ...e, sessao: { ...s, ...patch } };
}
function perguntarCancelamento(a) {
  out.acao = 'outra';
  out.alvo_id = a.id;
  out.sessao_patch = { etapa_atual: 'cancelar_confirma', aguardando_resposta: true, id_atend_alvo: a.id };
  out.texto = 'Você quer cancelar este horário?\n\n📅 ' + desc(a) + '\n💈' + (prof(a) || ' Atendimento') + '\n\nResponda *SIM* para cancelar ou *NÃO* para manter.\nSe preferir trocar de dia ou horário, responda *REMARCAR*.';
}

if (s.etapa_atual === 'cancelar_confirma') {
  const alvo = futuros.find(a => String(a.id) === String(s.id_atend_alvo));
  if (!alvo) {
    out.acao = 'outra';
    out.sessao_patch = concluir;
    out.texto = 'Não encontrei mais esse horário marcado. Se quiser agendar, é só mandar um oi! 🙂';
  } else if (sim) {
    out.acao = 'cancelar_confirmado';
    out.alvo_id = alvo.id;
    out.sessao_patch = concluir;
    out.cliente_patch = { status: futuros.some(a => a.id !== alvo.id) ? 'agendado' : 'em_atendimento' };
    out.texto = 'Pronto, seu horário de ' + desc(alvo) + ' foi cancelado. ✅\nQuando quiser marcar de novo, é só mandar um oi!';
  } else if (nao) {
    out.acao = 'outra';
    out.sessao_patch = concluir;
    out.texto = 'Combinado! Seu horário de ' + desc(alvo) + ' continua marcado. 👍';
  } else if (querRemarcar) {
    remarcar(alvo);
  } else {
    out.acao = 'outra';
    out.sessao_patch = { aguardando_resposta: true };
    out.texto = 'Não entendi 😅 Responda *SIM* para cancelar o horário de ' + desc(alvo) + ', *NÃO* para manter ou *REMARCAR* para trocar.';
  }
} else if (npsPendente && nota !== null && !emAgendamento) {
  out.acao = 'nps';
  out.alvo_id = npsPendente.id;
  out.nota = nota;
  out.texto = nota === 5
    ? 'Que bom saber! 🙌 Obrigado pela nota 5. Te esperamos na próxima! 💈'
    : nota === 4
      ? 'Obrigado pela nota 4! 😊 Vamos caprichar ainda mais para a próxima ser nota 5.'
      : 'Obrigado pela sinceridade 🙏 Sentimos muito que a experiência não foi como você esperava. Vamos repassar para a equipe.';
} else if (querRemarcar || querCancelar) {
  if (!proximo) {
    out.acao = 'outra';
    out.sessao_patch = concluir;
    out.texto = 'Não encontrei nenhum horário marcado para você. 🤔\nSe quiser agendar, é só mandar um oi!';
  } else if (querRemarcar) {
    remarcar(proximo);
  } else {
    perguntarCancelamento(proximo);
  }
} else if (s.id_atend_alvo && ['00101', '00201', '00301'].includes(s.etapa_atual)) {
  // Recomeçou o fluxo do zero: o próximo agendamento é novo, não remarcação
  out.acao = 'fluxo_limpar';
  out.sessao = { ...s, id_atend_alvo: null };
}

return [{ json: out }];
